"""IoT time-series ingestion and fleet management pattern."""
from __future__ import annotations

IOT_TIMESERIES_REQUIREMENTS = ["paho-mqtt>=1.6", "influxdb-client>=1.39"]

IOT_TIMESERIES_CODE = '''\
# iot_router.py — generated by AetherOS iot_timeseries pattern
from fastapi import APIRouter, Depends, HTTPException, Header, Query
from sqlalchemy.ext.asyncio import AsyncSession
from sqlalchemy import select, func, desc, and_
from typing import Optional, List
from datetime import datetime, timedelta, timezone
from database import get_db
from auth import get_current_user
import models
import logging

router = APIRouter(prefix="/iot", tags=["iot"])
logger = logging.getLogger(__name__)

# Maximum readings allowed in a single bulk insert
_BULK_LIMIT = 1000


# ── Device authentication helper ───────────────────────────────────────────────

async def _get_device_by_key(device_key: str, db: AsyncSession) -> "models.Device":
    """Authenticate a device by its device_key. Raises 401 if not found."""
    try:
        result = await db.execute(
            select(models.Device).where(models.Device.device_key == device_key)
        )
        device = result.scalar_one_or_none()
        if not device:
            raise HTTPException(status_code=401, detail="Invalid device key.")
        return device
    except HTTPException:
        raise
    except Exception as e:
        logger.warning("_get_device_by_key: db error key=%s: %s", device_key, e)
        raise HTTPException(status_code=500, detail="Device authentication failed.")


# ── Sensor reading ingestion ───────────────────────────────────────────────────

@router.post("/readings", status_code=201)
async def ingest_reading(
    payload: dict,
    x_device_key: str = Header(..., alias="X-Device-Key"),
    db: AsyncSession = Depends(get_db),
) -> dict:
    """Ingest a single sensor reading. Authenticates via X-Device-Key header."""
    device = await _get_device_by_key(x_device_key, db)
    try:
        reading = models.SensorReading(
            device_id=device.id,
            sensor_type=payload.get("sensor_type"),
            value=float(payload["value"]),
            unit=payload.get("unit", ""),
            quality=payload.get("quality", "good"),
            recorded_at=payload.get("recorded_at") or datetime.now(timezone.utc),
        )
        db.add(reading)

        # Update device last_seen_at and status to online
        from sqlalchemy import update  # noqa: PLC0415 — local to avoid circular at module level
        await db.execute(
            update(models.Device)
            .where(models.Device.id == device.id)
            .values(last_seen_at=datetime.now(timezone.utc), status="online")
        )

        await db.commit()
        await db.refresh(reading)
        return {"id": reading.id, "device_id": device.id, "recorded_at": str(reading.recorded_at)}
    except (KeyError, ValueError) as e:
        logger.warning("ingest_reading: invalid payload device=%s: %s", device.id, e)
        raise HTTPException(status_code=422, detail=f"Invalid payload: {e}")
    except Exception as e:
        logger.warning("ingest_reading: db error device=%s: %s", device.id, e)
        await db.rollback()
        raise HTTPException(status_code=500, detail="Failed to ingest reading.")


@router.post("/readings/bulk", status_code=201)
async def ingest_readings_bulk(
    payload: dict,
    x_device_key: str = Header(..., alias="X-Device-Key"),
    db: AsyncSession = Depends(get_db),
) -> dict:
    """Bulk ingest up to 1000 sensor readings in a single request."""
    device = await _get_device_by_key(x_device_key, db)
    readings_data: list = payload.get("readings", [])

    if len(readings_data) > _BULK_LIMIT:
        raise HTTPException(
            status_code=422,
            detail=f"Bulk limit is {_BULK_LIMIT} readings per request. Got {len(readings_data)}.",
        )
    if not readings_data:
        raise HTTPException(status_code=422, detail="readings list must not be empty.")

    try:
        objects = []
        for item in readings_data:
            try:
                objects.append(
                    models.SensorReading(
                        device_id=device.id,
                        sensor_type=item.get("sensor_type"),
                        value=float(item["value"]),
                        unit=item.get("unit", ""),
                        quality=item.get("quality", "good"),
                        recorded_at=item.get("recorded_at") or datetime.now(timezone.utc),
                    )
                )
            except (KeyError, ValueError) as e:
                logger.warning("ingest_bulk: skipping malformed item device=%s: %s", device.id, e)

        db.add_all(objects)

        from sqlalchemy import update  # noqa: PLC0415
        await db.execute(
            update(models.Device)
            .where(models.Device.id == device.id)
            .values(last_seen_at=datetime.now(timezone.utc), status="online")
        )

        await db.commit()
        return {"inserted": len(objects), "device_id": device.id}
    except Exception as e:
        logger.warning("ingest_readings_bulk: db error device=%s: %s", device.id, e)
        await db.rollback()
        raise HTTPException(status_code=500, detail="Bulk insert failed.")


# ── Time-series queries ────────────────────────────────────────────────────────

@router.get("/devices/{device_id}/readings")
async def get_device_readings(
    device_id: int,
    sensor_type: Optional[str] = Query(None),
    start: Optional[datetime] = Query(None),
    end: Optional[datetime] = Query(None),
    limit: int = Query(1000, ge=1, le=10000),
    db: AsyncSession = Depends(get_db),
    current_user=Depends(get_current_user),
) -> dict:
    """Time-series query for a device. Filters by sensor_type, start, end, limit."""
    try:
        conditions = [models.SensorReading.device_id == device_id]
        if sensor_type:
            conditions.append(models.SensorReading.sensor_type == sensor_type)
        if start:
            conditions.append(models.SensorReading.recorded_at >= start)
        if end:
            conditions.append(models.SensorReading.recorded_at <= end)

        result = await db.execute(
            select(models.SensorReading)
            .where(and_(*conditions))
            .order_by(desc(models.SensorReading.recorded_at))
            .limit(limit)
        )
        readings = result.scalars().all()
        return {
            "device_id": device_id,
            "items": [
                {
                    "id": r.id,
                    "sensor_type": r.sensor_type,
                    "value": r.value,
                    "unit": r.unit,
                    "quality": r.quality,
                    "recorded_at": str(r.recorded_at),
                }
                for r in readings
            ],
            "total": len(readings),
        }
    except Exception as e:
        logger.warning("get_device_readings: db error device=%s: %s", device_id, e)
        raise HTTPException(status_code=500, detail="Failed to fetch readings.")


@router.get("/devices/{device_id}/readings/summary")
async def get_readings_summary(
    device_id: int,
    start: Optional[datetime] = Query(None),
    end: Optional[datetime] = Query(None),
    db: AsyncSession = Depends(get_db),
    current_user=Depends(get_current_user),
) -> dict:
    """Min/max/avg/count per sensor_type for a device in the given time range."""
    try:
        if not start:
            start = datetime.now(timezone.utc) - timedelta(hours=24)
        if not end:
            end = datetime.now(timezone.utc)

        result = await db.execute(
            select(
                models.SensorReading.sensor_type,
                func.min(models.SensorReading.value).label("min_value"),
                func.max(models.SensorReading.value).label("max_value"),
                func.avg(models.SensorReading.value).label("avg_value"),
                func.count(models.SensorReading.id).label("count"),
            )
            .where(
                and_(
                    models.SensorReading.device_id == device_id,
                    models.SensorReading.recorded_at >= start,
                    models.SensorReading.recorded_at <= end,
                )
            )
            .group_by(models.SensorReading.sensor_type)
        )
        rows = result.all()
        return {
            "device_id": device_id,
            "start": str(start),
            "end": str(end),
            "summary": [
                {
                    "sensor_type": row.sensor_type,
                    "min": round(row.min_value, 4) if row.min_value is not None else None,
                    "max": round(row.max_value, 4) if row.max_value is not None else None,
                    "avg": round(float(row.avg_value), 4) if row.avg_value is not None else None,
                    "count": row.count,
                }
                for row in rows
            ],
        }
    except Exception as e:
        logger.warning("get_readings_summary: db error device=%s: %s", device_id, e)
        raise HTTPException(status_code=500, detail="Failed to compute summary.")


@router.get("/devices/{device_id}/status")
async def get_device_status(
    device_id: int,
    db: AsyncSession = Depends(get_db),
    current_user=Depends(get_current_user),
) -> dict:
    """Current device status plus the most recent reading per sensor_type."""
    try:
        device_result = await db.execute(
            select(models.Device).where(models.Device.id == device_id)
        )
        device = device_result.scalar_one_or_none()
        if not device:
            raise HTTPException(status_code=404, detail="Device not found.")

        # Latest reading per sensor_type via subquery
        subq = (
            select(
                models.SensorReading.sensor_type,
                func.max(models.SensorReading.recorded_at).label("latest_at"),
            )
            .where(models.SensorReading.device_id == device_id)
            .group_by(models.SensorReading.sensor_type)
            .subquery()
        )
        readings_result = await db.execute(
            select(models.SensorReading)
            .join(
                subq,
                and_(
                    models.SensorReading.sensor_type == subq.c.sensor_type,
                    models.SensorReading.recorded_at == subq.c.latest_at,
                    models.SensorReading.device_id == device_id,
                ),
            )
        )
        latest_readings = readings_result.scalars().all()

        return {
            "device_id": device.id,
            "name": device.name,
            "status": device.status,
            "last_seen_at": str(device.last_seen_at) if device.last_seen_at else None,
            "firmware_version": device.firmware_version,
            "latest_readings": [
                {
                    "sensor_type": r.sensor_type,
                    "value": r.value,
                    "unit": r.unit,
                    "recorded_at": str(r.recorded_at),
                }
                for r in latest_readings
            ],
        }
    except HTTPException:
        raise
    except Exception as e:
        logger.warning("get_device_status: db error device=%s: %s", device_id, e)
        raise HTTPException(status_code=500, detail="Failed to fetch device status.")


# ── Alert management ───────────────────────────────────────────────────────────

@router.get("/alerts")
async def list_alerts(
    status: Optional[str] = Query(None, regex="^(open|acknowledged|resolved)$"),
    severity: Optional[str] = Query(None, regex="^(critical|high|medium|low)$"),
    limit: int = Query(50, ge=1, le=200),
    offset: int = Query(0, ge=0),
    db: AsyncSession = Depends(get_db),
    current_user=Depends(get_current_user),
) -> dict:
    """Paginated alert list with optional status and severity filters."""
    try:
        conditions = []
        if status:
            conditions.append(models.Alert.status == status)
        if severity:
            conditions.append(models.Alert.severity == severity)

        query = select(models.Alert).order_by(desc(models.Alert.created_at)).offset(offset).limit(limit)
        if conditions:
            query = query.where(and_(*conditions))

        result = await db.execute(query)
        alerts = result.scalars().all()
        return {
            "items": [
                {
                    "id": a.id,
                    "device_id": a.device_id,
                    "alert_type": a.alert_type,
                    "severity": a.severity,
                    "sensor_type": a.sensor_type,
                    "trigger_value": a.trigger_value,
                    "message": a.message,
                    "status": a.status,
                    "created_at": str(a.created_at),
                    "resolved_at": str(a.resolved_at) if a.resolved_at else None,
                }
                for a in alerts
            ],
            "total": len(alerts),
        }
    except Exception as e:
        logger.warning("list_alerts: db error: %s", e)
        raise HTTPException(status_code=500, detail="Failed to fetch alerts.")


@router.post("/alerts/{alert_id}/acknowledge", status_code=200)
async def acknowledge_alert(
    alert_id: int,
    db: AsyncSession = Depends(get_db),
    current_user=Depends(get_current_user),
) -> dict:
    """Acknowledge an open alert."""
    try:
        result = await db.execute(select(models.Alert).where(models.Alert.id == alert_id))
        alert = result.scalar_one_or_none()
        if not alert:
            raise HTTPException(status_code=404, detail="Alert not found.")
        if alert.status != "open":
            raise HTTPException(status_code=409, detail=f"Alert is already {alert.status}.")

        alert.status = "acknowledged"
        await db.commit()
        return {"id": alert_id, "status": "acknowledged"}
    except HTTPException:
        raise
    except Exception as e:
        logger.warning("acknowledge_alert: db error alert=%s: %s", alert_id, e)
        await db.rollback()
        raise HTTPException(status_code=500, detail="Failed to acknowledge alert.")


@router.post("/alerts/{alert_id}/resolve", status_code=200)
async def resolve_alert(
    alert_id: int,
    db: AsyncSession = Depends(get_db),
    current_user=Depends(get_current_user),
) -> dict:
    """Resolve an open or acknowledged alert."""
    try:
        result = await db.execute(select(models.Alert).where(models.Alert.id == alert_id))
        alert = result.scalar_one_or_none()
        if not alert:
            raise HTTPException(status_code=404, detail="Alert not found.")
        if alert.status == "resolved":
            raise HTTPException(status_code=409, detail="Alert is already resolved.")

        alert.status = "resolved"
        alert.resolved_at = datetime.now(timezone.utc)
        await db.commit()
        return {"id": alert_id, "status": "resolved", "resolved_at": str(alert.resolved_at)}
    except HTTPException:
        raise
    except Exception as e:
        logger.warning("resolve_alert: db error alert=%s: %s", alert_id, e)
        await db.rollback()
        raise HTTPException(status_code=500, detail="Failed to resolve alert.")


# ── Command management ─────────────────────────────────────────────────────────

@router.post("/devices/{device_id}/commands", status_code=201)
async def queue_command(
    device_id: int,
    payload: dict,
    db: AsyncSession = Depends(get_db),
    current_user=Depends(get_current_user),
) -> dict:
    """Queue a control command for a device."""
    try:
        device_result = await db.execute(
            select(models.Device).where(models.Device.id == device_id)
        )
        if not device_result.scalar_one_or_none():
            raise HTTPException(status_code=404, detail="Device not found.")

        command = models.Command(
            device_id=device_id,
            command_type=payload.get("command_type"),
            payload=payload.get("payload", {}),
            status="pending",
        )
        db.add(command)
        await db.commit()
        await db.refresh(command)
        return {"id": command.id, "device_id": device_id, "status": "pending"}
    except HTTPException:
        raise
    except Exception as e:
        logger.warning("queue_command: db error device=%s: %s", device_id, e)
        await db.rollback()
        raise HTTPException(status_code=500, detail="Failed to queue command.")


@router.get("/devices/{device_id}/commands/pending")
async def list_pending_commands(
    device_id: int,
    db: AsyncSession = Depends(get_db),
    current_user=Depends(get_current_user),
) -> dict:
    """List pending commands for a device."""
    try:
        result = await db.execute(
            select(models.Command)
            .where(
                and_(
                    models.Command.device_id == device_id,
                    models.Command.status == "pending",
                )
            )
            .order_by(models.Command.created_at)
        )
        commands = result.scalars().all()
        return {
            "device_id": device_id,
            "items": [
                {
                    "id": c.id,
                    "command_type": c.command_type,
                    "payload": c.payload,
                    "status": c.status,
                    "created_at": str(c.created_at),
                }
                for c in commands
            ],
            "total": len(commands),
        }
    except Exception as e:
        logger.warning("list_pending_commands: db error device=%s: %s", device_id, e)
        raise HTTPException(status_code=500, detail="Failed to fetch commands.")


@router.post("/devices/{device_id}/commands/{command_id}/acknowledge", status_code=200)
async def acknowledge_command(
    device_id: int,
    command_id: int,
    x_device_key: str = Header(..., alias="X-Device-Key"),
    db: AsyncSession = Depends(get_db),
) -> dict:
    """Device acknowledges a command. Authenticates via X-Device-Key header."""
    device = await _get_device_by_key(x_device_key, db)
    if device.id != device_id:
        raise HTTPException(status_code=403, detail="Device key does not match device_id.")
    try:
        result = await db.execute(
            select(models.Command).where(
                and_(
                    models.Command.id == command_id,
                    models.Command.device_id == device_id,
                )
            )
        )
        command = result.scalar_one_or_none()
        if not command:
            raise HTTPException(status_code=404, detail="Command not found.")
        if command.status not in ("pending", "sent"):
            raise HTTPException(status_code=409, detail=f"Command is already {command.status}.")

        command.status = "acknowledged"
        command.executed_at = datetime.now(timezone.utc)
        await db.commit()
        return {"id": command_id, "status": "acknowledged", "executed_at": str(command.executed_at)}
    except HTTPException:
        raise
    except Exception as e:
        logger.warning("acknowledge_command: db error cmd=%s device=%s: %s", command_id, device_id, e)
        await db.rollback()
        raise HTTPException(status_code=500, detail="Failed to acknowledge command.")


# ── Dashboard summary ──────────────────────────────────────────────────────────

@router.get("/dashboard/summary")
async def dashboard_summary(
    db: AsyncSession = Depends(get_db),
    current_user=Depends(get_current_user),
) -> dict:
    """Fleet summary: total devices, online count, open alert count, readings in last hour."""
    try:
        one_hour_ago = datetime.now(timezone.utc) - timedelta(hours=1)
        offline_threshold = datetime.now(timezone.utc) - timedelta(minutes=5)

        total_result = await db.execute(select(func.count(models.Device.id)))
        total_devices = total_result.scalar() or 0

        online_result = await db.execute(
            select(func.count(models.Device.id)).where(
                models.Device.last_seen_at >= offline_threshold
            )
        )
        online_count = online_result.scalar() or 0

        alerts_result = await db.execute(
            select(func.count(models.Alert.id)).where(models.Alert.status == "open")
        )
        open_alerts = alerts_result.scalar() or 0

        readings_result = await db.execute(
            select(func.count(models.SensorReading.id)).where(
                models.SensorReading.recorded_at >= one_hour_ago
            )
        )
        readings_last_hour = readings_result.scalar() or 0

        return {
            "total_devices": total_devices,
            "online_count": online_count,
            "offline_count": total_devices - online_count,
            "open_alerts": open_alerts,
            "readings_last_hour": readings_last_hour,
        }
    except Exception as e:
        logger.warning("dashboard_summary: db error: %s", e)
        raise HTTPException(status_code=500, detail="Failed to fetch dashboard summary.")
'''

__all__ = ["IOT_TIMESERIES_CODE", "IOT_TIMESERIES_REQUIREMENTS"]
